#include <stdio.h>
#include <stdlib.h>
#include <float.h>

// Hungarian algorithm for min cost assignment, O(n^3)
// a: n x n cost matrix (row-major)
// returns assignment array col of size n (col[i] = assigned column for row i)
int* hungarian(double* a, int n) {
    double* u = calloc(n+1, sizeof(double)); // row potentials
    double* v = calloc(n+1, sizeof(double)); // col potentials
    int* p = calloc(n+1, sizeof(int));      // p[j] = row matched to col j
    int* way = calloc(n+1, sizeof(int));
    int* col = malloc(n * sizeof(int));

    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;
        double* minv = malloc((n+1) * sizeof(double));
        int* used = calloc(n+1, sizeof(int));
        for (int j = 0; j <= n; j++) minv[j] = DBL_MAX;
        do {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = DBL_MAX;
            int j1 = -1;
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = a[(i0-1)*n + (j-1)] - u[i0] - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
        free(minv);
        free(used);
    }
    for (int j = 1; j <= n; j++) {
        if (p[j] > 0) col[p[j]-1] = j-1;
    }
    free(u); free(v); free(p); free(way);
    return col;
}
```

