{"command":"cd /private/var/folders/bd/8xxg4c4j4rqc_6fqwvpxwnd80000gn/T/algotuneprobe_km4045_h/ep0; cat > auction.c << 'EOF'
#include <stdlib.h>
#include <float.h>
#include <math.h>

// Forward auction algorithm (maximization) with epsilon scaling.
// a: n x n cost matrix (row-major, double). We maximize sum a[i][assign[i]].
// Returns assign (size n), assign[i] = object assigned to person i.
int* auction(const double* a, int n) {
    double* p = (double*)calloc(n, sizeof(double));
    int* owner = (int*)malloc(n * sizeof(int));
    int* assign = (int*)malloc(n * sizeof(int));
    for (int j = 0; j < n; j++) owner[j] = -1;
    for (int i = 0; i < n; i++) assign[i] = -1;

    double maxc = 0;
    for (int i = 0; i < n*n; i++) if (a[i] > maxc) maxc = a[i];
    if (maxc <= 0) maxc = 1.0;

    double eps = maxc / 2.0;
    double eps_min = 1e-12;

    while (eps > eps_min) {
        for (int i = 0; i < n; i++) assign[i] = -1;
        for (int j = 0; j < n; j++) owner[j] = -1;
        int unassigned = n;
        while (unassigned > 0) {
            for (int i = 0; i < n && unassigned > 0; i++) {
                if (assign[i] != -1) continue;
                double best = -DBL_MAX, second = -DBL_MAX;
                int bestj = -1;
                const double* row = a + (size_t)i * n;
                for (int j = 0; j < n; j++) {
                    double v = row[j] - p[j];
                    if (v > best) { second = best; best = v; bestj = j; }
                    else if (v > second) { second = v; }
                }
                double bid = p[bestj] + (best - second) + eps;
                int prev = owner[bestj];
                if (prev != -1) { assign[prev] = -1; unassigned++; }
                owner[bestj] = i;
                assign[i] = bestj;
                p[bestj] = bid;
                unassigned--;
            }
        }
        eps /= 2.0;
    }
    free(p); free(owner);
    return assign;
}
EOF
