    double min, h, umin, usubmin, v2;
    int* free = (int*)malloc(n * sizeof(int));
    int* collist = (int*)malloc(n * sizeof(int));
    int* matches = (int*)malloc(n * sizeof(int));
    double* d = (double*)malloc(n * sizeof(double));
    int* pred = (int*)malloc(n * sizeof(int));
    int* rowsol = (int*)malloc(n * sizeof(int));
    int* colsol = (int*)malloc(n * sizeof(int));
    double* v = (double*)malloc(n * sizeof(double));

    for (i = 0; i < n; i++) matches[i] = 0;

    // column reduction
    for (j = n - 1; j >= 0; j--) {
        min = cost[j];
        imin = 0;
        for (i = 1; i < n; i++)
            if (cost[i*n + j] < min) { min = cost[i*n + j]; imin = i; }
        v[j] = min;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else
            colsol[j] = -1;
    }

    // reduction transfer
    for (i = 0; i < n; i++)
        if (matches[i] == 0) free[numfree++] = i;
        else if (matches[i] == 1) {
            j1 = rowsol[i];
            min = BIG;
            for (j = 0; j < n; j++)
                if (j != j1)
                    if (cost[i*n + j] - v[j] < min) min = cost[i*n + j] - v[j];
            v[j1] = v[j1] - min;
        }

    // augmenting row reduction
    for (loopcnt = 0; loopcnt < 2; loopcnt++) {
        k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k];
            k++;
            umin = cost[i*n] - v[0];
            j1 = 0;
            usubmin = BIG;
            for (j = 1; j < n; j++) {
                h = cost[i*n + j] - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin)
