                        break;
                    }
            }
            if (!unassignedfound) {
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = cost[i*n + j1] - v[j1] - min;
                for (k = up; k < n; k++) {
                    j = collist[k];
                    v2 = cost[i*n + j] - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == min) {
                            if (colsol[j] == -1) {
                                endofpath = j;
                                unassignedfound = 1;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up] = j;
                                up++;
                            }
                        }
                        d[j] = v2;
                    }
                }
