            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }

    free(free); free(collist); free(matches); free(d); free(pred); free(colsol); free(v);
    return rowsol;
}
