int_t _ccrrt_dense(const uint_t n, cost_t *cc, int_t *ii, int_t *jj, cost_t *u, cost_t *v)
{
    int_t i, j;
    cost_t min, h;

    for (i = 0; i < n; i++) {
        ii[i] = 0;
        jj[i] = 0;
        u[i] = 0;
        v[i] = 0;
    }

    for (j = 0; j < n; j++) {
        // find minimum in column j
        min = cc[j];
        i = 0;
        for (int_t k = 1; k < n; k++) {
            if (cc[k*n + j] < min) {
                min = cc[k*n + j];
                i = k;
            }
        }
        v[j] = min;
        if (++ii[i] == 1) {
            jj[i] = j;
        }
    }

    // reduction transfer
    for (i = 0; i < n; i++) {
        if (ii[i] == 0) {
            // free row
        } else if (ii[i] == 1) {
            j = jj[i];
            min = BIG;
            for (int_t k = 0; k < n; k++) {
                if (k != j) {
                    h = cc[i*n + k] - v[k];
                    if (h < min) min = h;
                }
            }
            v[j] -= min;
        }
    }
    return 0;
}
