#include <immintrin.h>
#include <stdlib.h>
#include <float.h>

// Single-epsilon forward auction with column-max init.
// Returns assign (size n), assign[i] = object for person i.
int* auction_single(const double* cost, int n, double eps, long long* nbids_out) {
    size_t nn = (size_t)n * n;
    double* a = (double*)malloc(nn * sizeof(double));
    double maxc = 0;
    for (size_t k = 0; k < nn; k++) {
        double v = -cost[k];
        a[k] = v;
        if (v > maxc) maxc = v;
    }
    if (maxc <= 0) maxc = 1.0;

    double* p = (double*)malloc(n * sizeof(double));
    int* owner = (int*)malloc(n * sizeof(int));
    int* assign = (int*)malloc(n * sizeof(int));

    for (int j = 0; j < n; j++) {
        double mx = -DBL_MAX;
        for (int i = 0; i < n; i++) {
            double v = a[(size_t)i * n + j];
            if (v > mx) mx = v;
        }
        p[j] = mx;
        owner[j] = -1;
    }
    for (int i = 0; i < n; i++) assign[i] = -1;

    long long nbids = 0;
    int unassigned = n;
    while (unassigned > 0) {
        for (int i = 0; i < n && unassigned > 0; i++) {
            if (assign[i] != -1) continue;
            double best = -DBL_MAX, second = -DBL_MAX;
            int bestj = -1;
            const double* row = a + (size_t)i * n;
            for (int j = 0; j < n; j++) {
                double v = row[j] - p[j];
                if (v > best) { second = best; best = v; bestj = j; }
                else if (v > second) { second = v; }
            }
            double bid = p[bestj] + (best - second) + eps;
            int prev = owner[bestj];
            if (prev != -1) { assign[prev] = -1; unassigned++; }
            owner[bestj] = i;
            assign[i] = bestj;
            p[bestj] = bid;
            unassigned--;
            nbids++;
        }
    }
    *nbids_out = nbids;
    free(a); free(p); free(owner);
    return assign;
}
EOF
